/* @autogenerated */
import { ComponentFixture, TestBed } from '@angular/core/testing';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { EditableSignatureComponent } from './editable-signature.component';

/** Lo que tarda el componente en preparar el lienzo tras pintarse. */
const ready = () => new Promise((resolve) => setTimeout(resolve, 150));

describe('EditableSignatureComponent', () => {
  let fixture: ComponentFixture<EditableSignatureComponent>;
  let component: EditableSignatureComponent;
  let changes: (string | null)[];

  const canvas = () => fixture.nativeElement.querySelector('canvas') as HTMLCanvasElement;
  const mouse = (type: string, x: number, y: number) =>
    canvas().dispatchEvent(new MouseEvent(type, { clientX: x, clientY: y, bubbles: true }));
  const touch = (type: string, x: number, y: number) => {
    const point = new Touch({ identifier: 1, target: canvas(), clientX: x, clientY: y });
    canvas().dispatchEvent(
      new TouchEvent(type, { touches: type === 'touchend' ? [] : [point], cancelable: true, bubbles: true }),
    );
  };

  beforeEach(async () => {
    TestBed.configureTestingModule({
      imports: [EditableSignatureComponent, TranslocoTestingModule.forRoot({ langs: { en: {} } })],
    });
    fixture = TestBed.createComponent(EditableSignatureComponent);
    fixture.nativeElement.style.display = 'block';
    fixture.nativeElement.style.width = '300px';
    component = fixture.componentInstance;
    changes = [];
    component.registerOnChange((value: string | null) => changes.push(value));
    fixture.detectChanges();
    await ready();
  });

  afterEach(() => TestBed.resetTestingModule());

  it('sizes the canvas to its wrapper', () => {
    const wrapper = canvas().parentElement!.getBoundingClientRect();

    expect(canvas().width).toBe(Math.floor(wrapper.width));
    expect(canvas().style.width).toBe(`${wrapper.width}px`);
  });

  it('saves the drawing as a black and white image when the stroke ends', () => {
    mouse('mousedown', 10, 10);
    mouse('mousemove', 40, 20);
    mouse('mouseup', 40, 20);

    expect(changes.length).toBe(1);
    expect(changes[0]).toMatch(/^data:image\/png;base64,/);
  });

  it('ignores the moves without a stroke and the leaving without drawing', () => {
    mouse('mousemove', 40, 20);
    mouse('mouseleave', 40, 20);

    expect(changes).toEqual([]);
  });

  it('draws with the finger too', () => {
    touch('touchstart', 10, 10);
    touch('touchmove', 30, 30);
    touch('touchend', 30, 30);

    expect(changes[0]).toMatch(/^data:image\/png;base64,/);
  });

  it('clears the signature', () => {
    mouse('mousedown', 10, 10);
    mouse('mouseup', 10, 10);

    component.clear();

    expect(changes.at(-1)).toBe('');
  });

  it('paints a signature it receives when the canvas is resized', async () => {
    const image = canvas().toDataURL('image/png');
    component.writeValue(image);
    const drawImage = spyOn(CanvasRenderingContext2D.prototype, 'drawImage');

    window.dispatchEvent(new Event('resize'));
    await new Promise((resolve) => setTimeout(resolve, 50));

    expect(drawImage).toHaveBeenCalled();
  });

  it('can not work without its canvas', () => {
    expect(() => (component as any).canva.call({ canvasRef: () => undefined })).toThrowError(/No native element/);
  });
});
